3: /** Local wall-clock schedules, with the same month-end clamp as saved reminders. */
4: export type ReminderForAlert = {
5:  id:string; title:string; memoryId?:string|null; dueDate:string; dueTime:string;
6:  repeat:RepeatSchedule; completed:boolean;
7: };
8: export type PlannedReminderAlert={id:string;key:string;timestamp:number;title:string;memoryId?:string|null};
9: function localDate(day:string,time:string):Date|null {
10:  if(!validReminderDay(day)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return null;
11:  const [y,m,d]=day.split("-").map(Number);
12:  const [hour,minute]=time.split(":").map(Number);
13:  const at=new Date(y,m-1,d,hour,minute,0,0);
14:  // DST gaps roll forward using native local-calendar interpretation.
15:  return Number.isFinite(at.getTime())?at:null;
16: }
17: export function planReminderAlerts(rows:readonly ReminderForAlert[],now=Date.now(),cap=48,perReminder=6):PlannedReminderAlert[]{
18:  const out:PlannedReminderAlert[]=[];
19:  for(const r of rows){
20:   if(r.completed||!r.title.trim()||!validReminderDay(r.dueDate))continue;
21:   let day=r.dueDate;
22:   const anchor=Number(day.slice(-2));
23:   for(let i=0,created=0;i<30000&&created<perReminder;i++){
24:    const at=localDate(day,r.dueTime);
25:    if(!at)break;
26:    const timestamp=at.getTime();
27:    if(timestamp>now+5000){
28:     out.push({id:r.id,key:r.id+"@"+timestamp,timestamp,title:r.title.trim(),memoryId:r.memoryId});
29:     created++;
30:    }
31:    if(r.repeat==="once")break;
32:    const next=nextReminderDay(day,r.repeat,anchor);
33:    if(!next||next===day)break;
34:    day=next;
35:   }
36:  }
37:  return out.sort((a,b)=>a.timestamp-b.timestamp||a.key.localeCompare(b.key)).slice(0,Math.max(0,Math.min(48,cap)));
38: }

