29:   if(!permission.granted&&askPermission&&permission.canAskAgain){
30:    permission=await requestPermissionsAsync();
31:   }
32:   if(!permission.granted)return "Saved locally. Notifications are off; enable alerts in device settings.";
33:   const desired=planReminderAlerts(rows);
34:   const next=new Map(desired.map(r=>[r.key,r]));
35:   const all=await getAllScheduledNotificationsAsync();
36:   const owned=all.filter(r=>r.content.data?.casitaDexType===OWNER);
37:   const valid=new Set<string>();
38:   // Schedule replacements before removing stale alerts to avoid a lost-alert window.
39:   for(const alert of desired){
40:    const found=owned.find(r=>r.content.data?.casitaDexKey===alert.key&&r.content.body===alert.title&&!valid.has(r.identifier));
41:    if(found){valid.add(found.identifier);continue;}
42:    const id=await scheduleNotificationAsync({
43:     content:{title:"CasitaDex reminder",body:alert.title,sound:"default",
44:      data:{casitaDexType:OWNER,casitaDexReminderId:alert.id,casitaDexMemoryId:alert.memoryId??null,casitaDexKey:alert.key}},
45:     trigger:{type:SchedulableTriggerInputTypes.DATE,
46:      date:new Date(alert.timestamp),...(Platform.OS==="android"?{channelId:CHANNEL}:{})},
47:    });
48:    valid.add(id);
49:   }
50:   for(const old of owned){
51:    if(!valid.has(old.identifier)||!next.has(String(old.content.data?.casitaDexKey??""))){
52:     await cancelScheduledNotificationAsync(old.identifier);
53:    }
54:   }
55:   return desired.length
56:    ? "Saved locally. Reminder alerts scheduled; device settings may affect timing."
57:    : "Saved locally. No upcoming reminder alert is due.";
58:  }catch{
59:   // Storage mutations are already committed; native alert errors never erase saved records.
60:   return "Saved locally. Alert scheduling needs attention; reopen Reminders to retry.";
61:  }
62: }
63: export function reconcileReminderNotifications(rows:readonly ReminderForAlert[],askPermission=false):Promise<string>{
64:  const next=pending.then(()=>run(rows,askPermission),()=>run(rows,askPermission));
