1: export type RepeatSchedule="once"|"daily"|"weekly"|"monthly"|"yearly";
2: const pad=(n:number)=>String(n).padStart(2,"0");
3: const year=(n:number)=>String(n).padStart(4,"0");
4: const utc=(y:number,m:number,d:number)=>{const x=new Date(0);x.setUTCHours(0,0,0,0);x.setUTCFullYear(y,m,d);return x;};
5: export function validReminderDay(day:string){
6:  if(!/^\d{4}-\d{2}-\d{2}$/.test(day))return false;
7:  const [y,m,d]=day.split("-").map(Number);
8:  if(y<1||y>9999||m<1||m>12||d<1)return false;
9:  return d<=utc(y,m,0).getUTCDate();
10: }
11: export function nextReminderDay(day:string,repeat:RepeatSchedule,anchorDay?:number){
12:  if(!validReminderDay(day))throw Error("Invalid reminder date");
13:  if(repeat==="once")return null;
14:  const [y,m,d]=day.split("-").map(Number);
15:  if(repeat==="daily"||repeat==="weekly"){
16:   const x=utc(y,m-1,d+(repeat==="daily"?1:7));
17:   if(x.getUTCFullYear()>9999)throw Error("Reminder exceeds supported calendar range");
18:   return [year(x.getUTCFullYear()),pad(x.getUTCMonth()+1),pad(x.getUTCDate())].join("-");
19:  }
20:  const target=repeat==="monthly"?{y:y+(m===12?1:0),m:m===12?1:m+1}:{y:y+1,m};
21:  if(target.y>9999)throw Error("Reminder exceeds supported calendar range");
22:  const last=utc(target.y,target.m,0).getUTCDate();
23:  return [year(target.y),pad(target.m),pad(Math.min(anchorDay??d,last))].join("-");
24: }

